#!/usr/bin/env python3
"""Builds phase-assignment-provenance-audit.md from the matrix and summary (numbers are never typed by hand).
Run after phase_provenance_audit.py:  python3 docs/food-profiles/build_provenance_report.py"""
import json

R = 'docs/food-profiles/'
S = json.load(open(R + 'phase-assignment-provenance-summary.json'))
M = json.load(open(R + 'phase-assignment-provenance-matrix.json'))['foods']
st = S['stages']
cc = S['classificationCounts']
sc = S['scientificSupportCounts']
rp = S['reviewPriorityCounts']
byid = {m['id']: m for m in M}
seeds = {k: byid[k] for k in S['conventionLinked']}
phases = ('menstrual', 'follicular', 'ovulatory', 'luteal')

L = []
w = L.append
w('# Food-to-phase assignment provenance audit\n')
w('**Documentation only. Nothing in the app, the catalogue (`assets/content`) or any phase mapping was changed.** This is a factual, non-legal audit of where the 142 food-to-phase assignments came from, written from Git history and repository documents. It does not conclude that anything was copied and does not clear anything legally. Machine-readable matrix: `phase-assignment-provenance-matrix.json` (summary: `phase-assignment-provenance-summary.json`). Regenerate with `phase_provenance_audit.py` and `build_provenance_report.py`.\n')
w('Evidence labels used throughout: **PROVEN** (shown by a commit or file), **INFERRED** (a reasonable reading of proven facts), **UNKNOWN** (the repository cannot establish it).\n')

w('## Summary\n')
w('**PROVEN**')
w(f'- Phase assignments first entered the repository on 11 Oct 2026 in commit `{st["56e981d"]["commit"]}` (design package, `design/content/ingredients.json`, 157 foods) and, the same day, in `{st["8828f98"]["commit"]}` (first bundled `assets/content/foods.json`, {st["8828f98"]["assignedFoods"]} foods assigned, "verbatim from the handoff").')
w('- The design package states the placements are the "current Emergent export (frontend/src/data/phases.ts)" and "Phase and category placement preserved exactly". The Emergent app is held in a private repository (`Andrea-Brezanova/moon-cycle`, commit `374f27f`); the recovery notes say its recipe data is labelled "SAMPLE CONTENT" and was generated by Emergent. They do not say whether the food lists carry that label.')
w(f'- The assignments were then replaced twice by owner curation ("Foods v2"): `{st["b2c071f"]["commit"]}` on 13 Oct (25 foods per phase, {st["b2c071f"]["assignedFoods"]} foods) and `{st["f9c0241"]["commit"]}` on 14 Oct (142 foods: 35/32/31/44). The current catalogue is identical to `f9c0241`; no assignment has changed since.')
w(f'- Of the 142 current assignments: **{cc["B"]}** keep the baseline phase, **{cc["E"]}** were moved to a different phase than the baseline, and **{cc["D"]}** were not in the baseline at all. {S["baselineFoodsNoLongerAssignedCount"]} baseline foods no longer have a phase.')
w('- The later USDA/NIH research (the 251 draft profiles and the 5 approved profiles) changed **no** phase assignment. It only added nutrient descriptions.')
w('- No file or commit message in the repository or in any of its 146 branch refs names Alisa Vitti, WomanCode, In the FLO, FLO Living or "Cycle Syncing" as a source. (Searches are in section 4.)')
w('- The design package\'s own review rated 146 of 161 baseline phase links "editorial" ("not evidence-based") and 15 "phase-relevant", and even for those 15 states that eating iron-rich food during the period "hasn\'t been shown to matter more than at other times".\n')
w('**INFERRED**')
w('- The original placement is a curated list of unknown authorship that arrived through the Emergent app (the recovery notes say Emergent generated its recipe data; how its food lists were produced is not recorded). Because the repository records no author for it, its own derivation could include a third-party chart, but nothing here shows that.')
w('- Foods v2 was a substantial rewrite by the owner: for the same food and phase, none of the 53 comparable per-food "why" texts is identical to the baseline, and the phase focus copy is almost entirely new. The phase placements were changed for about two fifths of the foods that existed in the baseline.')
w('- Three of the four "seed-cycling" seeds still sit in a phase the convention uses (sesame in menstrual, sunflower in luteal, flax in follicular); pumpkin seeds do not (moved from follicular/ovulatory to menstrual).\n')
w('**Limits of this report.** It uses only this repository\'s Git history and documents. The Emergent repository, the 2024 `mooncycle` repository and the Foods v2 research project were not part of that evidence base, and material found in them after this report was first written changes what can be said about the origin of the original list. That material is **withheld from this public repository pending the owner\'s decision** and is held in a private addendum. Read every "none found" below as "none found in this repository", not as evidence of independent origin.\n')
w('**UNKNOWN**')
w('- Where the Emergent list, or the 2024 `mooncycle` repository\'s ingredient sheet (which the recovery notes say "matches the Emergent food lists"), came from.')
w('- The research behind Foods v2: its rationale labels (`evidence_informed`, `framework_informed`, `supporting`, `editorial`) and USDA provenance live in a "research project" (`foods.provenance.json`) that is **not in this repository**.')
w('- Whether any specific external author\'s chart (including Alisa Vitti\'s) informed either list. The earlier conversation about inspiration is not recorded in the repository.\n')

w('## 1. Timeline of the dataset\n')
w('| Date | Commit | What changed | Phase-assigned foods | Per phase (men / fol / ovu / lut) |\n|---|---|---|---|---|')
for c in ('56e981d', '8828f98', 'b2c071f', 'f9c0241', 'HEAD'):
    s = st[c]
    pp = s['perPhase']
    w(f'| {s["date"]} | `{s["commit"]}` | {s["label"]} (`{s["file"]}`) | {s["assignedFoods"]} | {pp.get("menstrual")} / {pp.get("follicular")} / {pp.get("ovulatory")} / {pp.get("luteal")} |')
w('')
w('Notes:')
w(f'- `56e981d` has 157 foods in the design package; `8828f98` bundles the same 157 foods but shows {st["8828f98"]["assignedFoods"]} with phases, because Salt, Hijiki and Alcohol (moderate) were flagged "not ship-ready" in the design package and carried no phase copy when bundled.')
w('- `b2c071f` (13 Oct): "25 curated foods per phase ... Every previous food id is kept". `docs/decisions.md` (13 Oct) records: "each phase highlights exactly 25 owner-curated foods (nutrition framework, meal style, practicality, variety, recipe suitability)" and that the content "come[s] from the Moon Cycle Research production candidate". The ovulatory baseline copy "Support your liver ... to process the estrogen surge" and the broccoli sentence "Some cycle-syncing sources say these help the body process estrogen ... Moon Cycle doesn\'t make that claim" are in `8828f98` and absent from `b2c071f` onwards.')
w('- `f9c0241` (14 Oct): "Frozen Foods v2 checkpoint: 142 featured foods ... one featured phase each". 77 foods gained a phase and 14 changed phase relative to `b2c071f`.')
w('- After `f9c0241` the assignments are unchanged (`1c3cd36`, `d7e2883`, `1c3937f`, `8157bcb` touched `foods.json` for aisles, allergens and recipes only). The 24 Oct mapping audit (`c8dbf63`, `docs/food-content-audit-and-reference-profiles.md`) compared the current catalogue with a user-supplied `moon_cycle_142_food_profiles_editorial_draft.md` and found **0** phase differences; that markdown file is not in the repository, so it adds no independent origin.')
w('- Every later USDA research commit (profiles, drafts, audit) left `assets/content/foods.json` and `phases.json` untouched.\n')

w('## 2. Sources found\n')
w('| Source | Where | What it establishes |\n|---|---|---|')
w('| Design package ingredient model | `design/content/ingredients.json` (`56e981d`), `_about` | Baseline = Emergent export, "placement preserved exactly"; copy is "original Moon Cycle language". Each placement is annotated "Listed in Emergent <Phase> › <Category>". |')
w('| Per-phase "framework" lines | same file, `phases.*.framework` | Unnamed framework direction per phase (for example menstrual: "warming, mineral-rich foods; sea vegetables, dark beans, seafood"); seeds "(seed-cycling convention)". No author named. |')
w('| Per-placement evidence review | same file, `ingredients[].audit` | 146 "editorial", 15 "phase-relevant"; sources cited are mostly USDA FoodData Central, NIH ODS, EU claims register. Says "No published clinical trials support seed cycling". |')
w('| Recovery notes | `design/content/RECIPE-DATA-NEEDED.md` | Emergent source is private repo `Andrea-Brezanova/moon-cycle`, `frontend/src/data/phases.ts`, commit `374f27f`; recipe data there is labelled "SAMPLE CONTENT"; the 2024 `mooncycle` repository\'s ingredient sheet "matches the Emergent food lists". |')
w('| Technical plan | `docs/technical-plan.md` | The Emergent repository "is not on this machine"; its code and `phases.ts` were not inspected at that time. |')
w('| First bundled catalogue | `assets/content/foods.json` (`8828f98`) | "Verbatim from the handoff". |')
w('| Foods v2 | `b2c071f`, `f9c0241`, `docs/decisions.md`, `assets/content/README.md` | Owner-curated 25 per phase, then 142; rationale and USDA provenance held outside the repository. |')
w('| Mapping audit | `docs/food-content-audit-and-reference-profiles.md`, `docs/food-profiles/mapping-142.json` | All 142 entries equal the catalogue; verifies consistency only. |')
w('| Current phase copy | `assets/content/phases.json` | Menstrual focus states the iron rationale from NIH ODS; no author named. |\n')

w('## 3. Exact counts by provenance category\n')
w('Definitions used (operational, so every food can be classified from Git alone):\n')
w('- **A. Independently documented assignment**: a rationale for *placing this food in this phase* from an independent authoritative source. **None found.** The strongest documented rationale (iron losses in menstruation, NIH ODS) supports eating iron-rich food, not a phase placement, and the design review says so.')
w('- **B. Retained from the original list** (the "multiple-source editorial" category of the brief): the same phase in the Emergent baseline *and* in the owner-curated Foods v2. **The underlying sources of these placements are not identified, so their provenance is NOT independently established.** Two curation steps are not two independent sources: Foods v2 started from the baseline.')
w('- **C. Potentially derived from a specific external chart**: evidence tying a placement to a named chart. **None found.** (Seed foods are tracked separately as convention-linked; a "convention" is not a chart.)')
w('- **D. Source unknown**: not in the baseline and no rationale in the repository; added in Foods v2, whose research is outside the repository.')
w('- **E. Assignment changed**: in the baseline at a different phase, then moved in Foods v2. The commit messages describe owner curation from "independently researched nutrition", but that research is not in the repository, so "changed following independent review" is **INFERRED, not proven**.\n')
w('| Category | Foods |\n|---|---|')
for k, label in (('A', 'A. Independently documented'), ('B', 'B. Retained from the original list (sources not identified)'), ('C', 'C. Potentially derived from a specific chart'), ('D', 'D. Source unknown (new in Foods v2)'), ('E', 'E. Changed after baseline')):
    w(f'| {label} | {cc[k]} |')
w(f'| **Total** | **{sum(cc.values())}** |\n')
w('| Phase | A | B | C | D | E | Total |\n|---|---|---|---|---|---|---|')
for p in phases:
    d = S['perPhaseByClass'][p]
    w(f'| {p} | 0 | {d.get("B", 0)} | 0 | {d.get("D", 0)} | {d.get("E", 0)} | {sum(d.values())} |')
w('')
w(f'Review priority (matrix field `reviewPriority`): high {rp.get("high", 0)} (categories D and E, and the four seed foods), medium {rp.get("medium", 0)}, low {rp.get("low", 0)}. `furtherReviewRequired` is true for all 142 because no placement has a documented independent rationale.\n')
w(f'Baseline foods that no longer have a phase: {S["baselineFoodsNoLongerAssignedCount"]} (listed in the summary JSON), including Salt, Hijiki, Alcohol, Dulse and Kombu, which the design package flagged for safety or availability.\n')
w('Two examples of how the history reads: **spinach** is *ovulatory* in the baseline (`8828f98`), becomes menstrual-and-ovulatory in `b2c071f`, and menstrual only in `f9c0241`; **broccoli** moves from follicular to menstrual the same way. Both are now among the five approved nutrient profiles, whose cycle text rests on iron needs, not on the placement. The menstrual-phase iron story in `phases.json` therefore attaches to some foods whose original (Emergent) phase was a different one.\n')

w('## 4. Evidence for possible source dependence\n')
w('Searches of the working tree and of all history (`git log --all -S<term>`, 330 commits, 146 branch refs):\n')
w('| Term | Current tree | History |\n|---|---|---|')
w('| Vitti, WomanCode, Woman Code, FLO Living, Flo Living | 0 files | 0 commits |')
w('| In the FLO | 2 files, both the phrase "in the flour" (a recipe step and a recipe-API test fixture) | not a reference to a book or brand |')
w('| Cycle Syncing / cycle syncing | 0 files | 0 commits |')
w('| cycle-syncing | 1 file: `design/content/ingredients.json` (broccoli) | present in `56e981d` and `8828f98`; removed in `b2c071f`. Text: "Some cycle-syncing sources say these help the body process estrogen; human evidence is limited, so Moon Cycle doesn\'t make that claim." |')
w('| seed cycling / seed-cycling convention | `design/content/ingredients.json` | names the convention for flax, pumpkin, sesame and sunflower; the review says there are no clinical trials supporting it |')
w('| Emergent | design package, recovery notes, technical plan, `docs/decisions.md` | the documented immediate source of the baseline |\n')
w('What this does and does not show:\n')
w('- **Evidence of inspiration or awareness of a genre**: the generic phrases "cycle-syncing sources", "seed-cycling convention" and "framework direction" show the baseline was understood to follow a popular cycle-nutrition approach. They name no author, book or chart.')
w('- **No evidence of copying**: no external chart, extract, import file or script exists in the repository or its history, and no commit message mentions one. Two lists sharing common foods (kale, salmon, flaxseed) would not show copying either.')
w('- **Not done, and why**: I did not compare the lists with any third-party chart. None is in the repository, and the Emergent repository (the immediate source) was not available; a side-by-side against a named author\'s published material is for the owner or a qualified adviser.')
w(f'- **Distinctive presentation that survives from the baseline (PROVEN identical strings)**: the four season labels "Inner winter / Inner spring / Inner summer / Inner autumn" (baseline `8828f98` and current `phases.json`), and the follicular cooking line "Light steaming, quick sautés and fresh salads." (identical). The phase names themselves are standard terminology.')
w('- **Rewritten since the baseline**: taglines and focus copy (text similarity 0.03 to 0.39 for focus), all per-food "why" copy (0 of 53 comparable texts identical), and the ovulatory liver/estrogen wording.\n')
w('Seed foods and the convention (baseline phases -> current phase):\n')
w('| Food | Baseline | Current |\n|---|---|---|')
for k, m in seeds.items():
    w(f'| {m["name"]} | {" + ".join(m["baselinePhases"])} | {m["currentPhase"]} |')
w('')

w('## 5. Scientific-support classification (separate from provenance)\n')
w('Each placement was classified using only statements in the repository; nothing was invented. USDA composition alone never counts as support for a phase relationship.\n')
w('| Class | Meaning | Foods |\n|---|---|---|')
w(f'| Phase-specific nutritional requirement | Evidence that this food is needed in this phase | **0** (none identified; the design review says even the iron rationale is not shown to matter more during the period) |')
w(f'| Nutrient consideration for menstruating adults | A nutrient need that applies to people who menstruate (iron losses, NIH ODS), in the menstrual phase; true all month, not just in this phase | {sc.get("menstruating-adult-nutrient", 0)} |')
w(f'| Traditional or theoretical association | Placement tied to a named convention with no clinical evidence (seed cycling) | {sc.get("traditional-or-theoretical", 0)} |')
w(f'| General nutrition only | Composition documented (USDA), editorial phase link, no phase-specific evidence | {sc.get("general-nutrition-only", 0)} |')
w('| No reliable phase-specific evidence identified | Applies to **all 142** | 142 |\n')
w('Limited, mostly indirect research was noted for the luteal phase (calcium and fewer PMS symptoms, mostly from supplements; ginger and period pain, first days of menstruation). Those foods (collard, mustard greens, watercress, ginger, sesame) are no longer in the luteal phase in the current catalogue or are covered only by the baseline note, and the design review itself said to keep that out of short copy.\n')

w('## 6. Intellectual-property risk report (factual, not legal advice)\n')
w('No legal conclusion is drawn. In particular: **no infringement is alleged and no legal clearance is claimed.**\n')
w('| Area | Finding |\n|---|---|')
w('| Documented copying of an externally curated list | None documented in this repository. |')
w('| Dependence on one author\'s chart | Not shown, not excluded. The immediate source (Emergent export) has an unknown origin; the repository never records the earlier discussion of Alisa Vitti\'s approach. |')
w('| Unattributed or unclear source material | The baseline list (all 89 current foods that were in it, and 68 that no longer carry a phase) has no recorded author; the Foods v2 research is outside the repository, so 53 current placements have no recorded origin. |')
w('| Reproduced wording | Per-food and phase copy has been rewritten; surviving identical strings are the four "Inner <season>" labels and one cooking line (see section 4). Origin of those strings is UNKNOWN. |')
w('| Distinctive presentation | Four-phase structure with seasonal metaphors and per-phase food lists; seeds paired to phases in the baseline. A general genre of cycle-aware nutrition; whether any element is protectable or specific to one author is a question for counsel. |')
w('| Areas where independent reassessment is advisable | The four season labels; the seed-by-phase pairing; the baseline "framework direction" wording; the placement of all 142 foods until a documented method exists. |\n')
w('**Questions for a qualified intellectual-property attorney**\n')
w('1. Does a food-to-phase list, as a selection and arrangement of common foods, attract protection that matters here, and what separates inspiration from reproduction in this field?')
w('2. The baseline came from a private app built with Emergent, whose recipe data is labelled sample content. What does the owner need to establish about that tool\'s outputs and the 2024 `mooncycle` sheet before relying on them?')
w('3. Are "Inner winter / spring / summer / autumn" labels or the seed-by-phase pairing distinctive enough to warrant replacement or permission?')
w('4. Which records should be kept (Emergent export, the Foods v2 research project, conversations) to evidence independent development?\n')

w('## 7. Unresolved questions\n')
w('1. What is the origin of the Emergent phase lists and of the 2024 `mooncycle` ingredient sheet? (Needs the owner and the private repositories.)')
w('2. Can the Foods v2 "research project" (`foods.provenance.json` with its rationale labels) be added to the repository or exported? It is the single document most able to turn category D and E foods into documented ones.')
w('3. What did "framework_informed" refer to in Foods v2, and which foods carry that label?')
w('4. Was the `moon_cycle_142_food_profiles_editorial_draft.md` written from the catalogue or the other way round? (It matched the catalogue exactly; it is not in the repository.)')
w('5. Was any external chart consulted during the earlier discussions? Those records are not in the repository.')
w('6. Why were 36 baseline placements moved, and was that driven by nutrition research or by meal-style and variety (the stated criteria)?\n')

w('## 8. Recommended next steps (no content has been changed)\n')
w('| Group | Foods / items | Suggested action |\n|---|---|---|')
w('| Existing independently supported content | Nutrient profiles (USDA/NIH), cautions with sources, the phase-focus iron sentence | Keep. These do not depend on the phase list. |')
w(f'| Content needing an editorial rationale | All 142 placements ({cc["B"]} B, {cc["D"]} D, {cc["E"]} E) | Write one short rationale per placement from the owner\'s criteria (nutrition, meal style, practicality, variety, recipe fit). Bring in the Foods v2 research project if it exists. |')
w('| Content needing new evidence | Any wording that implies a phase-specific benefit | Remove the need: keep "suggestions, not rules"; do not seek evidence that does not exist. |')
w(f'| Content where source permission may be useful | Season labels; seed-by-phase pairing ({len(seeds)} foods) | Ask the owner whether these were taken from a named author; if so, seek permission or replace. |')
w(f'| Content where assignments could be reconsidered | The {len(seeds)} seed foods; the {cc["E"]} moved foods whose new phase rests only on editorial choice; the {sc.get("traditional-or-theoretical", 0)} convention-linked placements | Reassess after the rationale pass. This audit does not change them. |')
w('| Independent methodology | One page defining how a phase highlight is chosen | Criteria (nutrient density, variety, season, recipe fit), a per-food rationale record, a statement that highlights are suggestions, and a dated record of sources. Keeps the legitimate nutrition research and makes MoonCycle\'s method its own. |\n')
w('## Method and limits\n')
w('- Read from Git only: `git show <commit>:<file>` for `foods.json` (7 commits), `phases.json`, `design/content/ingredients.json`, commit messages and `docs/`. The generator is `phase_provenance_audit.py`; run it again to reproduce every number here.')
w('- Not inspected (not available): the private Emergent repository, the 2024 `mooncycle` repository, the Foods v2 research project, any chat history, any third-party chart.')
w('- The design package\'s "audit" blocks were written during the project (author not recorded beyond the committer, Andrea); they are treated as repository documentation, not as independent peer review.')
open(R + 'phase-assignment-provenance-audit.md', 'w').write('\n'.join(L) + '\n')
print('written', len(L), 'lines')
